    @Test
    fun `AoC 2015 Day 1 Part 1`() {
        test("""
            val input = first(arguments)
            var i = 0
            val l = length(input)
            var floor = 0
            while (i < l) {
                val c = charAt(input, i)
                floor = floor + when (c) {
                    ')' -> -1
                    '(' -> 1
                    else -> 0
                }
                i = i + 1
            }
            println floor
        """,
            "74\n",
            arrayOf(aoc2015day1))

    }

