            var i = 0
            val l = length(input)
            var floor = 0
            while (floor >= 0) {
                val c = charAt(input, i)
                floor = floor + when (c) {
                    ')' -> -1
                    '(' -> 1
                    else -> 0
                }
                i = i + 1
            }
            println i
        """,
